package vulnmatch

import (
	"testing"
)

// TestNpmFuzz replays randomized differential cases generated by
// scripts/gen_npm_fuzz.cjs against node-semver (includePrerelease=true).
func TestNpmFuzz(t *testing.T) {
	var data struct {
		Ranges []struct {
			Range    string `json:"range"`
			Version  string `json:"version"`
			Expected bool   `json:"expected"`
		} `json:"ranges"`
		InvalidRanges []string `json:"invalidRanges"`
		Compares      []struct {
			A        string `json:"a"`
			B        string `json:"b"`
			Expected int    `json:"expected"`
		} `json:"compares"`
	}
	loadJSON(t, "testdata/npm_fuzz.json", &data)
	for _, c := range data.Ranges {
		r, err := parseNpmRange(c.Range)
		if err != nil {
			t.Errorf("range %q: parse error: %v", c.Range, err)
			continue
		}
		v, err := parseSemver(c.Version)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.Version, err)
			continue
		}
		if got := r.satisfies(v); got != c.Expected {
			t.Errorf("satisfies(%q, %q) = %v, want %v", c.Version, c.Range, got, c.Expected)
		}
	}
	for _, rng := range data.InvalidRanges {
		if _, err := parseNpmRange(rng); err == nil {
			t.Errorf("range %q: parsed successfully, want error", rng)
		}
	}
	for _, c := range data.Compares {
		a, err := parseSemver(c.A)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.A, err)
			continue
		}
		b, err := parseSemver(c.B)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.B, err)
			continue
		}
		if got := compareSemver(a, b); got != c.Expected {
			t.Errorf("compare(%q, %q) = %d, want %d", c.A, c.B, got, c.Expected)
		}
	}
}

// TestPyPIFuzz replays randomized differential cases generated by
// scripts/gen_pypi_fuzz.py against pypa/packaging.
func TestPyPIFuzz(t *testing.T) {
	var data struct {
		Specs []struct {
			Spec     string `json:"spec"`
			Version  string `json:"version"`
			Expected bool   `json:"expected"`
		} `json:"specs"`
		Compares []struct {
			A        string `json:"a"`
			B        string `json:"b"`
			Expected int    `json:"expected"`
		} `json:"compares"`
	}
	loadJSON(t, "testdata/pypi_fuzz.json", &data)
	for _, c := range data.Specs {
		ss, err := parsePEP440SpecifierSet(c.Spec)
		if err != nil {
			t.Errorf("spec %q: parse error: %v", c.Spec, err)
			continue
		}
		v, err := parsePEP440(c.Version)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.Version, err)
			continue
		}
		if got := ss.contains(v); got != c.Expected {
			t.Errorf("contains(%q, %q) = %v, want %v", c.Version, c.Spec, got, c.Expected)
		}
	}
	for _, c := range data.Compares {
		a, err := parsePEP440(c.A)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.A, err)
			continue
		}
		b, err := parsePEP440(c.B)
		if err != nil {
			t.Errorf("version %q: parse error: %v", c.B, err)
			continue
		}
		if got := comparePEP440(a, b); got != c.Expected {
			t.Errorf("compare(%q, %q) = %d, want %d", c.A, c.B, got, c.Expected)
		}
	}
}
